python3 - <<'E'
p='src/pricing.js'
s=open(p).read()
s=s.replace('''/** Subtotal and discount for''','''/** Points multiplier by membership tier; any other member earns one point per dollar. */
const TIER_MULTIPLIERS = { silver: 2, gold: 3 };

/** Flat points added to an order that ships express. */
const EXPRESS_BONUS = 50;

/** Share of points kept: discounted orders keep half, except gold members who keep all. */
function keptShare(membership, discounted) {
  return discounted && membership !== "gold" ? 0.5 : 1;
}

/**
 * Loyalty points for an order: one per whole dollar of the net cents, times the tier
 * multiplier, plus the express bonus, halved (rounded down) when a discount code was
 * used unless the member is gold. Always a whole number.
 */
export function loyaltyPoints(netCents, { membership, express, discounted }) {
  const multiplier = TIER_MULTIPLIERS[membership] ?? 1;
  const bonus = express ? EXPRESS_BONUS : 0;
  const earned = Math.floor(netCents / 100) * multiplier + bonus;
  return Math.floor(earned * keptShare(membership, discounted));
}

/** Subtotal and discount for''')
open(p,'w').write(s)
p='src/orders.js'
s=open(p).read()
s=s.replace('import { priceCart }','import { loyaltyPoints, priceCart }')
s=s.replace('discountCode, region, zone, express }','discountCode, region, zone, express, membership }')
s=s.replace('''    total: price.net''','''    points: loyaltyPoints(price.net, { membership, express, discounted: price.discount > 0 }),
    total: price.net''')
open(p,'w').write(s)
E
cat >> test/pricing.test.js <<'E'

test("points are one per whole dollar of the net, rounded down", () => {
  assert.equal(loyaltyPoints(2399, {}), 23);
  assert.equal(loyaltyPoints(99, {}), 0);
});

test("silver earns double and gold triple", () => {
  assert.equal(loyaltyPoints(2300, { membership: "silver" }), 46);
  assert.equal(loyaltyPoints(2300, { membership: "gold" }), 69);
});

test("express shipping adds a 50 point bonus", () => {
  assert.equal(loyaltyPoints(2300, { express: true }), 73);
});

test("a discount code halves the points, rounded down, except for gold", () => {
  assert.equal(loyaltyPoints(2300, { discounted: true }), 11);
  assert.equal(loyaltyPoints(2300, { membership: "silver", discounted: true }), 23);
  assert.equal(loyaltyPoints(2300, { membership: "gold", discounted: true, express: true }), 119);
  assert.equal(loyaltyPoints(2300, { express: true, discounted: true }), 36);
});
E
